"""Create an ignored same-origin narrow-viewport QA harness for the supported preview."""
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
HTML='''<!doctype html><html lang="en"><meta charset="utf-8"><title>Binary School viewport QA</title><style>body{font:16px sans-serif;background:#e8eeeb;color:#173f36;margin:20px}iframe{border:2px solid #617e70;background:white;height:900px;flex:none}.frames{display:flex;gap:24px;overflow:auto}label,button,select{font:inherit;margin:8px}pre{white-space:pre-wrap;background:white;padding:15px}</style><h1>Binary School viewport QA</h1><p>Maintainer fixture, not a student lesson. Use a disposable browser profile: frames share the site's browser storage. This tests CSS viewport widths, not physical devices or screen readers.</p><label>Page <select id="route"><option value="home">Overview</option><option value="lesson/0">Environment lesson</option><option value="lesson/108">Flag lesson</option><option value="resources">Resources</option><option value="final">Patch practice</option><option value="paths">Study paths</option></select></label><button id="measure">Measure rendered layouts</button><pre id="report" role="status">Wait for the pages, then measure.</pre><div class="frames"><section><h2>375 CSS pixels</h2><iframe title="375px viewport" width="375" src="index.html#home"></iframe></section><section><h2>768 CSS pixels</h2><iframe title="768px viewport" width="768" src="index.html#home"></iframe></section><section><h2>1280 CSS pixels</h2><iframe title="1280px viewport" width="1280" src="index.html#home"></iframe></section></div><script>const frames=[...document.querySelectorAll('iframe')];document.querySelector('#route').onchange=e=>frames.forEach(f=>f.src='index.html#'+e.target.value);document.querySelector('#measure').onclick=()=>{document.querySelector('#report').textContent=JSON.stringify(frames.map(f=>{const d=f.contentDocument;return {viewport:f.clientWidth,documentWidth:d.documentElement.clientWidth,contentWidth:d.documentElement.scrollWidth,overflow:d.documentElement.scrollWidth>d.documentElement.clientWidth,heading:d.querySelector('h1')?.textContent,lessonOutlineOpen:d.querySelector('.lessonoutline')?.open,focused:d.activeElement?.tagName}}),null,2)};</script></html>'''
if __name__=='__main__':
    target=ROOT/'site/qa-browser.html'
    target.write_text(HTML)
    print('Created',target)
    print('Use /qa-browser.html on the supported preview; remove this generated file after QA.')
